import json, yaml
from collections import Counter

with open('/home/ubuntu/.claude-account-4/projects/-home-ubuntu--agent-ml-research-idea-gen-0509-3-projects-solver-trace-ablation--claude-sessions-agent-79f408c6/8c20cf77-1617-4a4f-baa8-f3d4720387e8/tool-results/mcp-agent-ml-research-read_registry-1779196212386.txt') as f:
    data = json.load(f)

result_yaml = data['result']
parsed = yaml.safe_load(result_yaml)
experiments = parsed['data']['experiments']  # dict keyed by exp_id

# d143 experiments
print('=== d143 experiments ===')
for eid, exp in experiments.items():
    if 'd143' in str(eid).lower():
        if isinstance(exp, dict):
            hyp = str(exp.get('hypothesis', ''))[:50]
            print(f'  {eid} | status={exp.get(\"status\")} | conclusion={exp.get(\"conclusion\", \"-\")} | hyp={hyp}')
        else:
            print(f'  {eid} | value_type={type(exp)}')

# llama experiments
print()
print('=== llama experiments ===')
for eid, exp in experiments.items():
    if 'llama' in str(eid).lower():
        if isinstance(exp, dict):
            hyp = str(exp.get('hypothesis', ''))[:50]
            print(f'  {eid} | status={exp.get(\"status\")} | conclusion={exp.get(\"conclusion\", \"-\")} | hyp={hyp}')
        else:
            print(f'  {eid} | value_type={type(exp)}')

# Status counts
print()
print('=== Status counts ===')
counts = Counter()
for eid, exp in experiments.items():
    if isinstance(exp, dict):
        counts[exp.get('status', 'UNKNOWN')] += 1
    else:
        counts['NON-DICT'] += 1

for s in ['RUNNING', 'PREPARING', 'PENDING', 'QUEUED', 'ALLOCATED', 'DONE', 'KILLED']:
    if counts.get(s, 0) > 0:
        print(f'  {s}: {counts[s]}')
for s, c in sorted(counts.items()):
    if s not in ['RUNNING', 'PREPARING', 'PENDING', 'QUEUED', 'ALLOCATED', 'DONE', 'KILLED']:
        print(f'  {s}: {c}')
print(f'  TOTAL: {len(experiments)}')
